// 4 theme-aware tints matching DHIRA design tokens
const TINT_CLASSES = [
  "fill-[rgb(var(--blue-subtle))] text-[rgb(var(--blue-subtle))]",
  "fill-[rgb(var(--blue-border))] text-[rgb(var(--blue-border))]",
  "fill-[rgb(var(--blue-400))]/50 text-[rgb(var(--blue-400))]",
  "fill-[rgb(var(--blue))]/70 text-[rgb(var(--blue))]",
];

const IndiaStateMap = memo(function IndiaStateMap({
  className = "w-full max-w-[240px] sm:max-w-[260px]",
}: {
  className?: string;
}) {
  return (
    <svg
      viewBox="0 0 612 696"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-label="Map of India showing fragmented state-wise systems across 28 states"
      role="img"
      className={className}
    >
      <g stroke="rgb(var(--primary-bg))" strokeWidth="1.2" strokeLinejoin="round" strokeLinecap="round">
        {INDIA_LOCATIONS.map((loc, idx) => {
          const tintIndex = (idx * 7 + 11) % TINT_CLASSES.length;
          const tintClass = TINT_CLASSES[tintIndex];
          const isPulsing = idx % 7 === 0;

          return (
            <path
              key={loc.id}
              id={loc.id}
              d={loc.path}
              className={`transition-opacity duration-300 hover:opacity-90 ${tintClass} ${
                isPulsing ? "animate-pulse" : ""
              }`}
            >
              <title>{loc.name}</title>
            </path>
          );
        })}
      </g>
    </svg>
  );
});

export default IndiaStateMap;
